commands.cmd:
set -u
P="$HOME/.local/share/codex-ecosystem/tools/promptfoo-0.123.1"
p=$(command -v promptfoo) || { echo "FAIL: promptfoo is not on PATH"; exit 1; }
r=$(readlink -f "$p") || { echo "FAIL: readlink -f $p exited $?"; exit 1; }
case "$r" in "$P"/lib/node_modules/promptfoo/*) ;; *) echo "FAIL: promptfoo on PATH ($p) resolves to $r, outside $P/lib/node_modules/promptfoo"; exit 1 ;; esac
V=$(DO_NOT_TRACK=1 PROMPTFOO_DISABLE_TELEMETRY=1 PROMPTFOO_DISABLE_UPDATE=1 timeout 20 promptfoo --version) || { echo "FAIL: promptfoo --version exited $?"; exit 1; }
[ "$V" = "0.123.1" ] || { echo "FAIL: promptfoo --version printed '$V', expected 0.123.1"; exit 1; }
L=$(DO_NOT_TRACK=1 npm_config_audit=false npm_config_fund=false timeout 30 npm ls --global --prefix "$P" --depth=0 --json) || { echo "FAIL: npm ls --global --prefix $P --depth=0 exited $?"; exit 1; }
TOP=$(python3 -c '
import json, sys
top = {name: meta.get("version") for name, meta in (json.loads(sys.argv[1]).get("dependencies") or {}).items()}
assert top == {"promptfoo": "0.123.1"}, top
print(top)
' "$L") || { echo "FAIL: npm ls --global --prefix $P does not list promptfoo 0.123.1 as its only top-level package: $L"; exit 1; }
echo "PASS promptfoo --version $V | npm ls --global --prefix $P --depth=0: $TOP"
echo "PATH promptfoo: $p -> $r"
